script:
test('rounds the 3.125 tie from 3.7, 3.3 and 2.0 over 8 credits half to even to 3.12', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '3.7', credits: '3' }, { gradePoints: '3.3', credits: '3' }, { gradePoints: '2.0', credits: '2' }] });
  assert.deepEqual(actual, { gpa: '3.12' });
});

test('rounds the 2.675 tie from four one-credit grades half to even to 2.68', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '4.0', credits: '1' }, { gradePoints: '3.0', credits: '1' }, { gradePoints: '2.0', credits: '1' }, { gradePoints: '1.7', credits: '1' }] });
  assert.deepEqual(actual, { gpa: '2.68' });
});

test('returns no gpa when the course list is empty', function () {
  var actual = code.calculateGpa({ courses: [] });
  assert.deepEqual(actual, { gpa: null });
});

test('returns no gpa when a non-empty list has total credits of zero', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '4.0', credits: '0.0' }] });
  assert.deepEqual(actual, { gpa: null });
});

test('ignores a zero-credit course in the middle and still returns 3.50', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '4.0', credits: '3' }, { gradePoints: '1.7', credits: '0' }, { gradePoints: '2.0', credits: '1' }] });
  assert.deepEqual(actual, { gpa: '3.50' });
});

test('returns 0.00 for a real zero average instead of no gpa', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '0', credits: '1' }] });
  assert.deepEqual(actual, { gpa: '0.00' });
});

test('rounds 3.1125 to the nearer value 3.11', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '3.7', credits: '3' }, { gradePoints: '3.2', credits: '3' }, { gradePoints: '2.1', credits: '2' }] });
  assert.deepEqual(actual, { gpa: '3.11' });
});

test('rounds 3.1375 to the nearer value 3.14', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '3.8', credits: '3' }, { gradePoints: '3.3', credits: '3' }, { gradePoints: '1.9', credits: '2' }] });
  assert.deepEqual(actual, { gpa: '3.14' });
});

test('rounds 2.674, one step below halfway, to 2.67', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '2.674', credits: '1' }] });
  assert.deepEqual(actual, { gpa: '2.67' });
});

test('rounds 2.676, one step above halfway, to 2.68', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '2.676', credits: '1' }] });
  assert.deepEqual(actual, { gpa: '2.68' });
});

test('rounds 1.2251, just above a tie, up to 1.23', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '1.2251', credits: '1' }] });
  assert.deepEqual(actual, { gpa: '1.23' });
});

test('rounds 1.2349 to 1.23 without stage-rounding the 9 into a tie', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '1.2349', credits: '1' }] });
  assert.deepEqual(actual, { gpa: '1.23' });
});

test('rounds only the final quotient so 2.006 becomes 2.01', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '1.003', credits: '1' }, { gradePoints: '3.009', credits: '1' }] });
  assert.deepEqual(actual, { gpa: '2.01' });
});

test('accepts mixed integer and decimal strings and still returns 3.50', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '4', credits: '3.0' }, { gradePoints: '2.0', credits: '1' }] });
  assert.deepEqual(actual, { gpa: '3.50' });
});

test('does not treat a leading zero-credit course as no gpa and returns 3.50', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '1.7', credits: '0' }, { gradePoints: '4.0', credits: '3' }, { gradePoints: '2.0', credits: '1' }] });
  assert.deepEqual(actual, { gpa: '3.50' });
});

test('keeps a trailing zero-credit course in the sum and returns 3.50', function () {
  var actual = code.calculateGpa({ courses: [{ gradePoints: '4.0', credits: '3' }, { gradePoints: '2.0', credits: '1' }, { gradePoints: '1.7', credits: '0' }] });
  assert.deepEqual(actual, { gpa: '3.50' });
});
